import React, { useState, useEffect, useRef, useCallback } from 'react';
import { createRoot } from 'react-dom/client';
import { Target, Zap, Play, RotateCcw, Home, HelpCircle, Trophy, AlertTriangle } from 'lucide-react';

// --- Constants & Types ---

type GameMode = 'multiples' | 'divisors';
type GameState = 'menu' | 'playing' | 'gameover' | 'victory';

interface Point {
  x: number;
  y: number;
}

interface Ball {
  id: number;
  value: number;
  pos: number; // 0 to 1 along the path
  color: string;
}

interface Projectile {
  x: number;
  y: number;
  vx: number;
  vy: number;
  value: number;
  color: string;
}

const COLORS = [
  '#f43f5e', // rose
  '#06b6d4', // cyan
  '#8b5cf6', // violet
  '#10b981', // emerald
  '#f59e0b', // amber
];

const BALL_RADIUS = 20;
const PROJECTILE_SPEED = 12;
const PATH_SAMPLES = 1000;
const INITIAL_SPEED = 0.0002;
const SPEED_INCREMENT = 0.00005;

// --- Utility Functions ---

const getRandomInt = (min: number, max: number) => Math.floor(Math.random() * (max - min + 1)) + min;

const getConditionMatch = (val: number, target: number, mode: GameMode): boolean => {
  if (mode === 'multiples') {
    return val % target === 0;
  } else {
    // Divisors: target is divisible by val
    return val !== 0 && target % val === 0;
  }
};

// Generate a smooth spiral path
const generatePath = (width: number, height: number): Point[] => {
  const points: Point[] = [];
  const centerX = width / 2;
  const centerY = height / 2;
  const maxRadius = Math.min(width, height) * 0.45;
  const loops = 3;

  for (let i = 0; i <= PATH_SAMPLES; i++) {
    const t = i / PATH_SAMPLES;
    // We want the path to start from the edge and spiral inwards
    const angle = t * Math.PI * 2 * loops;
    const radius = maxRadius * (1 - t * 0.8);
    points.push({
      x: centerX + Math.cos(angle) * radius,
      y: centerY + Math.sin(angle) * radius,
    });
  }
  return points;
};

// --- Main Component ---

const ZumaMathGame = () => {
  const [gameState, setGameState] = useState<GameState>('menu');
  const [gameMode, setGameMode] = useState<GameMode>('multiples');
  const [targetNumber, setTargetNumber] = useState<number>(5);
  const [score, setScore] = useState<number>(0);
  const [level, setLevel] = useState<number>(1);
  const [highScore, setHighScore] = useState<number>(0);

  const canvasRef = useRef<HTMLCanvasElement>(null);
  const requestRef = useRef<number>();
  const pathRef = useRef<Point[]>([]);
  const ballsRef = useRef<Ball[]>([]);
  const projectilesRef = useRef<Projectile[]>([]);
  const shooterAngleRef = useRef<number>(0);
  const nextBallValueRef = useRef<number>(5);
  const currentBallValueRef = useRef<number>(5);
  const mousePosRef = useRef<Point>({ x: 0, y: 0 });
  const gameSpeedRef = useRef<number>(INITIAL_SPEED);
  const lastTimeRef = useRef<number>(0);
  const ballCounterRef = useRef<number>(0);

  // Initialize Level
  const initLevel = (lvl: number, mode: GameMode) => {
    let target = 0;
    if (mode === 'multiples') {
      target = getRandomInt(2, 9);
    } else {
      // For divisors, pick a number with many divisors
      const choices = [12, 16, 18, 20, 24, 30, 36, 40, 48, 60];
      target = choices[getRandomInt(0, choices.length - 1)];
    }

    setTargetNumber(target);
    setScore(0);
    setLevel(lvl);
    gameSpeedRef.current = INITIAL_SPEED + (lvl - 1) * SPEED_INCREMENT;
    projectilesRef.current = [];
    ballCounterRef.current = 0;

    // Initial balls
    const initialBalls: Ball[] = [];
    for (let i = 0; i < 10 + lvl * 2; i++) {
      initialBalls.push(generateRandomBall(-i * 0.035, target, mode));
    }
    ballsRef.current = initialBalls;

    // Prepare shooter
    currentBallValueRef.current = generateFairBallValue(target, mode);
    nextBallValueRef.current = generateFairBallValue(target, mode);
  };

  const generateRandomBall = (pos: number, target: number, mode: GameMode): Ball => {
    const value = generateFairBallValue(target, mode);
    return {
      id: ballCounterRef.current++,
      value,
      pos,
      color: COLORS[getRandomInt(0, COLORS.length - 1)],
    };
  };

  const generateFairBallValue = (target: number, mode: GameMode): number => {
    const isMatch = Math.random() > 0.4; // 60% chance of getting a "matching" number
    if (mode === 'multiples') {
      if (isMatch) return target * getRandomInt(1, 10);
      return getRandomInt(1, 50);
    } else {
      if (isMatch) {
        const divisors = [];
        for (let i = 1; i <= target; i++) if (target % i === 0) divisors.push(i);
        return divisors[getRandomInt(0, divisors.length - 1)];
      }
      return getRandomInt(1, target + 10);
    }
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const rect = canvas.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;
    mousePosRef.current = { x, y };

    const centerX = canvas.width / 2;
    const centerY = canvas.height / 2;
    shooterAngleRef.current = Math.atan2(y - centerY, x - centerX);
  };

  const handleShoot = () => {
    if (gameState !== 'playing') return;
    const canvas = canvasRef.current;
    if (!canvas) return;

    const centerX = canvas.width / 2;
    const centerY = canvas.height / 2;
    const angle = shooterAngleRef.current;

    projectilesRef.current.push({
      x: centerX + Math.cos(angle) * 40,
      y: centerY + Math.sin(angle) * 40,
      vx: Math.cos(angle) * PROJECTILE_SPEED,
      vy: Math.sin(angle) * PROJECTILE_SPEED,
      value: currentBallValueRef.current,
      color: '#ffffff', // Projectiles are white for high contrast
    });

    currentBallValueRef.current = nextBallValueRef.current;
    nextBallValueRef.current = generateFairBallValue(targetNumber, gameMode);
  };

  const update = (time: number) => {
    if (gameState !== 'playing') return;

    const deltaTime = time - lastTimeRef.current;
    lastTimeRef.current = time;

    // 1. Move balls along path
    let gameOver = false;
    ballsRef.current.forEach((ball, idx) => {
      // Speed up if balls are too far apart to keep the chain? 
      // Simplified: constant speed for now
      ball.pos += gameSpeedRef.current;
      if (ball.pos >= 1) gameOver = true;
    });

    if (gameOver) {
      setGameState('gameover');
      return;
    }

    // 2. Move projectiles and detect collisions
    const path = pathRef.current;
    projectilesRef.current = projectilesRef.current.filter((proj) => {
      proj.x += proj.vx;
      proj.y += proj.vy;

      // Off screen check
      if (proj.x < 0 || proj.x > 800 || proj.y < 0 || proj.y > 600) return false;

      // Collision check with balls
      for (let i = 0; i < ballsRef.current.length; i++) {
        const ball = ballsRef.current[i];
        if (ball.pos < 0) continue; // Don't hit balls not yet visible

        const pathIdx = Math.floor(ball.pos * (PATH_SAMPLES - 1));
        const ballPoint = path[pathIdx];

        const dist = Math.sqrt((proj.x - ballPoint.x) ** 2 + (proj.y - ballPoint.y) ** 2);

        if (dist < BALL_RADIUS * 1.5) {
          handleHit(ball, proj.value, i);
          return false; // Remove projectile
        }
      }
      return true;
    });

    // 3. Check for victory
    if (ballsRef.current.length === 0) {
      setGameState('victory');
    }

    draw();
    requestRef.current = requestAnimationFrame(update);
  };

  const handleHit = (hitBall: Ball, shotValue: number, ballIndex: number) => {
    // Check if both the shot ball and the hit ball satisfy the level's condition
    const shotMatches = getConditionMatch(shotValue, targetNumber, gameMode);
    const hitMatches = getConditionMatch(hitBall.value, targetNumber, gameMode);

    if (shotMatches && hitMatches) {
      // Clear a chain of matching neighbors
      let toRemove = [ballIndex];

      // Look forward
      for (let j = ballIndex + 1; j < ballsRef.current.length; j++) {
        if (getConditionMatch(ballsRef.current[j].value, targetNumber, gameMode)) {
          toRemove.push(j);
        } else break;
      }
      // Look backward
      for (let j = ballIndex - 1; j >= 0; j--) {
        if (getConditionMatch(ballsRef.current[j].value, targetNumber, gameMode)) {
          toRemove.push(j);
        } else break;
      }

      setScore(prev => prev + toRemove.length * 100);
      ballsRef.current = ballsRef.current.filter((_, idx) => !toRemove.includes(idx));
    } else {
      // Insert the shot ball into the line if it didn't cause a clear
      const newBall: Ball = {
        id: ballCounterRef.current++,
        value: shotValue,
        pos: hitBall.pos - 0.03, // Place it slightly behind
        color: COLORS[getRandomInt(0, COLORS.length - 1)],
      };

      const newBalls = [...ballsRef.current];
      newBalls.splice(ballIndex, 0, newBall);
      ballsRef.current = newBalls;

      // Adjust positions to prevent overlap
      for (let i = 1; i < ballsRef.current.length; i++) {
        if (ballsRef.current[i].pos > ballsRef.current[i-1].pos - 0.035) {
          ballsRef.current[i].pos = ballsRef.current[i-1].pos - 0.035;
        }
      }
    }
  };

  const draw = useCallback(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    // Clear
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // Draw Path (Glowy)
    ctx.beginPath();
    ctx.strokeStyle = 'rgba(255, 255, 255, 0.1)';
    ctx.lineWidth = 40;
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';
    pathRef.current.forEach((p, i) => {
      if (i === 0) ctx.moveTo(p.x, p.y);
      else ctx.lineTo(p.x, p.y);
    });
    ctx.stroke();

    // Draw "The Hole" (End of path)
    const endPoint = pathRef.current[PATH_SAMPLES];
    ctx.beginPath();
    ctx.fillStyle = '#000';
    ctx.shadowBlur = 15;
    ctx.shadowColor = '#f00';
    ctx.arc(endPoint.x, endPoint.y, 25, 0, Math.PI * 2);
    ctx.fill();
    ctx.shadowBlur = 0;

    // Draw Balls
    ballsRef.current.forEach((ball) => {
      if (ball.pos < 0 || ball.pos > 1) return;
      const pIdx = Math.floor(ball.pos * (PATH_SAMPLES - 1));
      const p = pathRef.current[pIdx];

      // Glow effect for matching balls
      const isMatch = getConditionMatch(ball.value, targetNumber, gameMode);
      if (isMatch) {
        ctx.shadowBlur = 15;
        ctx.shadowColor = ball.color;
      }

      ctx.beginPath();
      ctx.fillStyle = ball.color;
      ctx.arc(p.x, p.y, BALL_RADIUS, 0, Math.PI * 2);
      ctx.fill();

      ctx.shadowBlur = 0;
      ctx.fillStyle = '#fff';
      ctx.font = 'bold 14px Inter, sans-serif';
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.fillText(ball.value.toString(), p.x, p.y);
    });

    // Draw Projectiles
    projectilesRef.current.forEach((proj) => {
      ctx.beginPath();
      ctx.fillStyle = proj.color;
      ctx.shadowBlur = 10;
      ctx.shadowColor = '#fff';
      ctx.arc(proj.x, proj.y, 10, 0, Math.PI * 2);
      ctx.fill();
      ctx.shadowBlur = 0;

      ctx.fillStyle = '#000';
      ctx.font = 'bold 10px Inter, sans-serif';
      ctx.fillText(proj.value.toString(), proj.x, proj.y);
    });

    // Draw Shooter (Turret)
    const centerX = canvas.width / 2;
    const centerY = canvas.height / 2;
    ctx.save();
    ctx.translate(centerX, centerY);
    ctx.rotate(shooterAngleRef.current);

    // Turret Body
    ctx.fillStyle = '#333';
    ctx.beginPath();
    ctx.roundRect(-20, -15, 60, 30, 8);
    ctx.fill();

    // Muzzle glow
    ctx.fillStyle = '#06b6d4';
    ctx.fillRect(35, -5, 5, 10);
    ctx.restore();

    // Center Hub with Current Value
    ctx.beginPath();
    ctx.fillStyle = '#1e293b';
    ctx.strokeStyle = '#06b6d4';
    ctx.lineWidth = 3;
    ctx.arc(centerX, centerY, 35, 0, Math.PI * 2);
    ctx.fill();
    ctx.stroke();

    ctx.fillStyle = '#fff';
    ctx.font = 'bold 24px Inter, sans-serif';
    ctx.fillText(currentBallValueRef.current.toString(), centerX, centerY);

    ctx.font = '12px Inter, sans-serif';
    ctx.fillStyle = 'rgba(255,255,255,0.6)';
    ctx.fillText('NEXT: ' + nextBallValueRef.current.toString(), centerX, centerY + 55);

  }, [gameState, targetNumber, gameMode]);

  useEffect(() => {
    pathRef.current = generatePath(800, 600);
    if (gameState === 'playing') {
      requestRef.current = requestAnimationFrame(update);
    }
    return () => {
      if (requestRef.current) cancelAnimationFrame(requestRef.current);
    };
  }, [gameState]);

  const startGame = (mode: GameMode) => {
    setGameMode(mode);
    setGameState('playing');
    initLevel(1, mode);
  };

  const restartGame = () => {
    setGameState('playing');
    initLevel(1, gameMode);
  };

  const nextLevel = () => {
    setGameState('playing');
    initLevel(level + 1, gameMode);
  };

  useEffect(() => {
    const stored = localStorage.getItem('zuma_math_highscore');
    if (stored) setHighScore(parseInt(stored));
  }, []);

  useEffect(() => {
    if (score > highScore) {
      setHighScore(score);
      localStorage.setItem('zuma_math_highscore', score.toString());
    }
  }, [score, highScore]);

  return (
    <div className="min-h-screen bg-slate-950 text-white font-sans flex flex-col items-center justify-center overflow-hidden">
      {/* HUD */}
      {gameState === 'playing' && (
        <div className="absolute top-0 left-0 w-full p-6 flex justify-between items-start pointer-events-none z-10">
          <div className="bg-slate-900/80 backdrop-blur-md p-4 rounded-2xl border border-slate-800 shadow-xl">
            <div className="flex items-center gap-3 mb-1">
              <div className="p-2 bg-indigo-500/20 rounded-lg">
                <Target className="w-5 h-5 text-indigo-400" />
              </div>
              <span className="text-slate-400 text-sm font-medium uppercase tracking-wider">Mission</span>
            </div>
            <h2 className="text-2xl font-bold">
              {gameMode === 'multiples' ? 'Multiples' : 'Divisors'} of{' '}
              <span className="text-indigo-400 underline decoration-indigo-400/30">{targetNumber}</span>
            </h2>
          </div>

          <div className="flex flex-col items-end gap-3">
            <div className="bg-slate-900/80 backdrop-blur-md p-4 rounded-2xl border border-slate-800 shadow-xl min-w-[140px]">
              <div className="text-slate-400 text-xs font-medium uppercase tracking-widest mb-1 text-right">Score</div>
              <div className="text-3xl font-black text-right tabular-nums text-transparent bg-clip-text bg-gradient-to-r from-cyan-400 to-blue-500">
                {score.toLocaleString()}
              </div>
            </div>
            <div className="bg-slate-900/80 backdrop-blur-md px-4 py-2 rounded-xl border border-slate-800 shadow-xl text-sm text-slate-400 font-bold">
              LEVEL {level}
            </div>
          </div>
        </div>
      )}

      {/* Main Canvas Area */}
      <div className="relative group">
        <canvas
          ref={canvasRef}
          width={800}
          height={600}
          onMouseMove={handleMouseMove}
          onClick={handleShoot}
          className={`rounded-3xl shadow-2xl bg-slate-900 border border-slate-800 transition-opacity duration-500 ${gameState !== 'playing' ? 'opacity-20 grayscale' : 'opacity-100'}`}
        />

        {/* Menu Overlays */}
        {gameState === 'menu' && (
          <div className="absolute inset-0 flex flex-col items-center justify-center bg-slate-950/40 backdrop-blur-sm rounded-3xl p-8 text-center animate-in fade-in zoom-in duration-300">
            <div className="mb-8 p-6 bg-indigo-600 rounded-full shadow-[0_0_50px_rgba(79,70,229,0.5)] animate-pulse">
              <Zap className="w-16 h-16 text-white" />
            </div>
            <h1 className="text-6xl font-black mb-2 tracking-tighter bg-clip-text text-transparent bg-gradient-to-b from-white to-slate-400">
              MATH ZUMA
            </h1>
            <p className="text-slate-400 mb-12 max-w-md text-lg">
              Shoot the numbers that match the target condition. Clear the line before it reaches the end!
            </p>

            <div className="grid grid-cols-2 gap-6 w-full max-w-lg">
              <button
                onClick={() => startGame('multiples')}
                className="group relative flex flex-col items-center p-8 bg-slate-900 border border-slate-800 rounded-3xl hover:border-indigo-500 transition-all hover:-translate-y-1 hover:shadow-[0_20px_40px_-15px_rgba(79,70,229,0.3)]"
              >
                <div className="mb-4 p-4 bg-indigo-500/10 rounded-2xl group-hover:bg-indigo-500/20 transition-colors">
                  <Play className="w-8 h-8 text-indigo-400" />
                </div>
                <span className="font-bold text-xl mb-1">Multiples</span>
                <span className="text-slate-500 text-sm">Target: N × X</span>
              </button>

              <button
                onClick={() => startGame('divisors')}
                className="group relative flex flex-col items-center p-8 bg-slate-900 border border-slate-800 rounded-3xl hover:border-cyan-500 transition-all hover:-translate-y-1 hover:shadow-[0_20px_40px_-15px_rgba(6,182,212,0.3)]"
              >
                <div className="mb-4 p-4 bg-cyan-500/10 rounded-2xl group-hover:bg-cyan-500/20 transition-colors">
                  <Target className="w-8 h-8 text-cyan-400" />
                </div>
                <span className="font-bold text-xl mb-1">Divisors</span>
                <span className="text-slate-500 text-sm">Target / X = Integer</span>
              </button>
            </div>

            <div className="mt-12 flex items-center gap-2 text-slate-500">
              <Trophy className="w-4 h-4" />
              <span className="text-sm font-medium uppercase tracking-widest">High Score: {highScore}</span>
            </div>
          </div>
        )}

        {gameState === 'gameover' && (
          <div className="absolute inset-0 flex flex-col items-center justify-center bg-slate-950/60 backdrop-blur-md rounded-3xl p-8 text-center animate-in fade-in zoom-in duration-300">
            <div className="mb-6 p-5 bg-rose-500/20 rounded-full border border-rose-500/30">
              <AlertTriangle className="w-12 h-12 text-rose-500" />
            </div>
            <h2 className="text-5xl font-black mb-2 text-white">GAME OVER</h2>
            <p className="text-slate-400 mb-8 text-lg">The numbers reached the black hole!</p>

            <div className="bg-slate-900/50 p-6 rounded-2xl border border-slate-800 mb-8 w-64">
              <div className="text-slate-500 text-xs uppercase tracking-widest mb-1">Final Score</div>
              <div className="text-4xl font-bold text-indigo-400">{score.toLocaleString()}</div>
            </div>

            <div className="flex gap-4">
              <button
                onClick={restartGame}
                className="flex items-center gap-2 px-8 py-4 bg-indigo-600 hover:bg-indigo-500 rounded-2xl font-bold text-white transition-all hover:scale-105"
              >
                <RotateCcw className="w-5 h-5" />
                Retry Level
              </button>
              <button
                onClick={() => setGameState('menu')}
                className="flex items-center gap-2 px-8 py-4 bg-slate-800 hover:bg-slate-700 rounded-2xl font-bold text-white transition-all"
              >
                <Home className="w-5 h-5" />
                Main Menu
              </button>
            </div>
          </div>
        )}

        {gameState === 'victory' && (
          <div className="absolute inset-0 flex flex-col items-center justify-center bg-indigo-950/40 backdrop-blur-md rounded-3xl p-8 text-center animate-in fade-in zoom-in duration-300">
            <div className="mb-6 p-5 bg-emerald-500/20 rounded-full border border-emerald-500/30">
              <Trophy className="w-16 h-16 text-emerald-500" />
            </div>
            <h2 className="text-5xl font-black mb-2 text-white uppercase tracking-tight">Level Complete!</h2>
            <p className="text-slate-300 mb-8 text-lg">You cleared all the mathematical anomalies.</p>

            <div className="flex flex-col items-center bg-slate-900/80 p-6 rounded-3xl border border-indigo-500/30 mb-10 w-80 shadow-2xl">
              <div className="text-indigo-400 text-xs uppercase tracking-widest mb-1 font-bold">Bonus Points Earned</div>
              <div className="text-5xl font-black text-white mb-4">+500</div>
              <div className="w-full h-px bg-slate-800 mb-4"></div>
              <div className="text-slate-400 text-xs uppercase tracking-widest mb-1">Total Score</div>
              <div className="text-3xl font-bold text-transparent bg-clip-text bg-gradient-to-r from-emerald-400 to-cyan-400">
                {(score + 500).toLocaleString()}
              </div>
            </div>

            <div className="flex gap-4">
              <button
                onClick={nextLevel}
                className="flex items-center gap-2 px-10 py-5 bg-emerald-600 hover:bg-emerald-500 rounded-2xl font-black text-xl text-white transition-all hover:scale-105 shadow-[0_0_30px_rgba(16,185,129,0.3)]"
              >
                <Play className="w-6 h-6 fill-current" />
                Next Level
              </button>
              <button
                onClick={() => setGameState('menu')}
                className="flex items-center gap-2 px-8 py-5 bg-slate-800 hover:bg-slate-700 rounded-2xl font-bold text-white transition-all"
              >
                <Home className="w-5 h-5" />
                Menu
              </button>
            </div>
          </div>
        )}
      </div>

      {/* Footer Info */}
      <div className="mt-8 flex items-center gap-12 text-slate-500 text-sm font-medium uppercase tracking-widest">
        <div className="flex items-center gap-2">
          <HelpCircle className="w-4 h-4 text-indigo-400" />
          <span>Aim with Mouse, Click to Fire</span>
        </div>
        <div className="flex items-center gap-2">
          <Zap className="w-4 h-4 text-amber-400" />
          <span>Match both Shot & Ball to pop chains</span>
        </div>
      </div>

      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;700;900&display=swap');
        body { margin: 0; background: #020617; font-family: 'Inter', sans-serif; cursor: crosshair; }
        canvas { touch-action: none; cursor: crosshair; }
        .animate-pulse-slow { animation: pulse 4s cubic-bezier(0.4, 0, 0.6, 1) infinite; }
        @keyframes pulse { 0%, 100% { opacity: 1; } 50% { opacity: .7; } }
      `}</style>
    </div>
  );
};

// Render
const rootElement = document.getElementById('root');
if (rootElement) {
  createRoot(rootElement).render(<ZumaMathGame />);
}

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { createRoot } from 'react-dom/client';
import { Target, Zap, Play, RotateCcw, Home, HelpCircle, Trophy, AlertTriangle } from 'lucide-react';

// --- Constants & Types ---

type GameMode = 'multiples' | 'divisors';
type GameState = 'menu' | 'playing' | 'gameover' | 'victory';

interface Point {
  x: number;
  y: number;
}

interface Ball {
  id: number;
  value: number;
  pos: number; // 0 to 1 along the path
  color: string;
}

interface Projectile {
  x: number;
  y: number;
  vx: number;
  vy: number;
  value: number;
  color: string;
}

const COLORS = [
  '#f43f5e', // rose
  '#06b6d4', // cyan
  '#8b5cf6', // violet
  '#10b981', // emerald
  '#f59e0b', // amber
];

const BALL_RADIUS = 20;
const PROJECTILE_SPEED = 12;
const PATH_SAMPLES = 1000;
const INITIAL_SPEED = 0.0002;
const SPEED_INCREMENT = 0.00005;

// --- Utility Functions ---

const getRandomInt = (min: number, max: number) => Math.floor(Math.random() * (max - min + 1)) + min;

const getConditionMatch = (val: number, target: number, mode: GameMode): boolean => {
  if (mode === 'multiples') {
    return val % target === 0;
  } else {
    // Divisors: target is divisible by val
    return val !== 0 && target % val === 0;
  }
};

// Generate a smooth spiral path
const generatePath = (width: number, height: number): Point[] => {
  const points: Point[] = [];
  const centerX = width / 2;
  const centerY = height / 2;
  const maxRadius = Math.min(width, height) * 0.45;
  const loops = 3;

  for (let i = 0; i <= PATH_SAMPLES; i++) {
    const t = i / PATH_SAMPLES;
    // We want the path to start from the edge and spiral inwards
    const angle = t * Math.PI * 2 * loops;
    const radius = maxRadius * (1 - t * 0.8);
    points.push({
      x: centerX + Math.cos(angle) * radius,
      y: centerY + Math.sin(angle) * radius,
    });
  }
  return points;
};

// --- Main Component ---

const ZumaMathGame = () => {
  const [gameState, setGameState] = useState<GameState>('menu');
  const [gameMode, setGameMode] = useState<GameMode>('multiples');
  const [targetNumber, setTargetNumber] = useState<number>(5);
  const [score, setScore] = useState<number>(0);
  const [level, setLevel] = useState<number>(1);
  const [highScore, setHighScore] = useState<number>(0);

  const canvasRef = useRef<HTMLCanvasElement>(null);
  const requestRef = useRef<number>();
  const pathRef = useRef<Point[]>([]);
  const ballsRef = useRef<Ball[]>([]);
  const projectilesRef = useRef<Projectile[]>([]);
  const shooterAngleRef = useRef<number>(0);
  const nextBallValueRef = useRef<number>(5);
  const currentBallValueRef = useRef<number>(5);
  const mousePosRef = useRef<Point>({ x: 0, y: 0 });
  const gameSpeedRef = useRef<number>(INITIAL_SPEED);
  const lastTimeRef = useRef<number>(0);
  const ballCounterRef = useRef<number>(0);

  // Initialize Level
  const initLevel = (lvl: number, mode: GameMode) => {
    let target = 0;
    if (mode === 'multiples') {
      target = getRandomInt(2, 9);
    } else {
      // For divisors, pick a number with many divisors
      const choices = [12, 16, 18, 20, 24, 30, 36, 40, 48, 60];
      target = choices[getRandomInt(0, choices.length - 1)];
    }

    setTargetNumber(target);
    setScore(0);
    setLevel(lvl);
    gameSpeedRef.current = INITIAL_SPEED + (lvl - 1) * SPEED_INCREMENT;
    projectilesRef.current = [];
    ballCounterRef.current = 0;

    // Initial balls
    const initialBalls: Ball[] = [];
    for (let i = 0; i < 10 + lvl * 2; i++) {
      initialBalls.push(generateRandomBall(-i * 0.035, target, mode));
    }
    ballsRef.current = initialBalls;

    // Prepare shooter
    currentBallValueRef.current = generateFairBallValue(target, mode);
    nextBallValueRef.current = generateFairBallValue(target, mode);
  };

  const generateRandomBall = (pos: number, target: number, mode: GameMode): Ball => {
    const value = generateFairBallValue(target, mode);
    return {
      id: ballCounterRef.current++,
      value,
      pos,
      color: COLORS[getRandomInt(0, COLORS.length - 1)],
    };
  };

  const generateFairBallValue = (target: number, mode: GameMode): number => {
    const isMatch = Math.random() > 0.4; // 60% chance of getting a "matching" number
    if (mode === 'multiples') {
      if (isMatch) return target * getRandomInt(1, 10);
      return getRandomInt(1, 50);
    } else {
      if (isMatch) {
        const divisors = [];
        for (let i = 1; i <= target; i++) if (target % i === 0) divisors.push(i);
        return divisors[getRandomInt(0, divisors.length - 1)];
      }
      return getRandomInt(1, target + 10);
    }
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const rect = canvas.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;
    mousePosRef.current = { x, y };

    const centerX = canvas.width / 2;
    const centerY = canvas.height / 2;
    shooterAngleRef.current = Math.atan2(y - centerY, x - centerX);
  };

  const handleShoot = () => {
    if (gameState !== 'playing') return;
    const canvas = canvasRef.current;
    if (!canvas) return;

    const centerX = canvas.width / 2;
    const centerY = canvas.height / 2;
    const angle = shooterAngleRef.current;

    projectilesRef.current.push({
      x: centerX + Math.cos(angle) * 40,
      y: centerY + Math.sin(angle) * 40,
      vx: Math.cos(angle) * PROJECTILE_SPEED,
      vy: Math.sin(angle) * PROJECTILE_SPEED,
      value: currentBallValueRef.current,
      color: '#ffffff', // Projectiles are white for high contrast
    });

    currentBallValueRef.current = nextBallValueRef.current;
    nextBallValueRef.current = generateFairBallValue(targetNumber, gameMode);
  };

  const update = (time: number) => {
    if (gameState !== 'playing') return;

    const deltaTime = time - lastTimeRef.current;
    lastTimeRef.current = time;

    // 1. Move balls along path
    let gameOver = false;
    ballsRef.current.forEach((ball, idx) => {
      ball.pos += gameSpeedRef.current;
      if (ball.pos >= 1) gameOver = true;
    });

    if (gameOver) {
      setGameState('gameover');
      return;
    }

    // 2. Move projectiles and detect collisions
    const path = pathRef.current;
    projectilesRef.current = projectilesRef.current.filter((proj) => {
      proj.x += proj.vx;
      proj.y += proj.vy;

      // Off screen check
      if (proj.x < 0 || proj.x > 800 || proj.y < 0 || proj.y > 600) return false;

      // Collision check with balls
      for (let i = 0; i < ballsRef.current.length; i++) {
        const ball = ballsRef.current[i];
        if (ball.pos < 0) continue; // Don't hit balls not yet visible

        const pathIdx = Math.floor(ball.pos * (PATH_SAMPLES - 1));
        const ballPoint = path[pathIdx];

        const dist = Math.sqrt((proj.x - ballPoint.x) ** 2 + (proj.y - ballPoint.y) ** 2);

        if (dist < BALL_RADIUS * 1.5) {
          handleHit(ball, proj.value, i);
          return false; // Remove projectile
        }
      }
      return true;
    });

    // 3. Check for victory
    if (ballsRef.current.length === 0) {
      setGameState('victory');
    }

    draw();
    requestRef.current = requestAnimationFrame(update);
  };

  const handleHit = (hitBall: Ball, shotValue: number, ballIndex: number) => {
    const shotMatches = getConditionMatch(shotValue, targetNumber, gameMode);
    const hitMatches = getConditionMatch(hitBall.value, targetNumber, gameMode);

    if (shotMatches && hitMatches) {
      let toRemove = [ballIndex];
      for (let j = ballIndex + 1; j < ballsRef.current.length; j++) {
        if (getConditionMatch(ballsRef.current[j].value, targetNumber, gameMode)) {
          toRemove.push(j);
        } else break;
      }
      for (let j = ballIndex - 1; j >= 0; j--) {
        if (getConditionMatch(ballsRef.current[j].value, targetNumber, gameMode)) {
          toRemove.push(j);
        } else break;
      }

      setScore(prev => prev + toRemove.length * 100);
      ballsRef.current = ballsRef.current.filter((_, idx) => !toRemove.includes(idx));
    } else {
      const newBall: Ball = {
        id: ballCounterRef.current++,
        value: shotValue,
        pos: hitBall.pos - 0.03,
        color: COLORS[getRandomInt(0, COLORS.length - 1)],
      };

      const newBalls = [...ballsRef.current];
      newBalls.splice(ballIndex, 0, newBall);
      ballsRef.current = newBalls;

      for (let i = 1; i < ballsRef.current.length; i++) {
        if (ballsRef.current[i].pos > ballsRef.current[i-1].pos - 0.035) {
          ballsRef.current[i].pos = ballsRef.current[i-1].pos - 0.035;
        }
      }
    }
  };

  const draw = useCallback(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    ctx.beginPath();
    ctx.strokeStyle = 'rgba(255, 255, 255, 0.1)';
    ctx.lineWidth = 40;
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';
    pathRef.current.forEach((p, i) => {
      if (i === 0) ctx.moveTo(p.x, p.y);
      else ctx.lineTo(p.x, p.y);
    });
    ctx.stroke();

    const endPoint = pathRef.current[PATH_SAMPLES];
    ctx.beginPath();
    ctx.fillStyle = '#000';
    ctx.shadowBlur = 15;
    ctx.shadowColor = '#f00';
    ctx.arc(endPoint.x, endPoint.y, 25, 0, Math.PI * 2);
    ctx.fill();
    ctx.shadowBlur = 0;

    ballsRef.current.forEach((ball) => {
      if (ball.pos < 0 || ball.pos > 1) return;
      const pIdx = Math.floor(ball.pos * (PATH_SAMPLES - 1));
      const p = pathRef.current[pIdx];

      const isMatch = getConditionMatch(ball.value, targetNumber, gameMode);
      if (isMatch) {
        ctx.shadowBlur = 15;
        ctx.shadowColor = ball.color;
      }

      ctx.beginPath();
      ctx.fillStyle = ball.color;
      ctx.arc(p.x, p.y, BALL_RADIUS, 0, Math.PI * 2);
      ctx.fill();

      ctx.shadowBlur = 0;
      ctx.fillStyle = '#fff';
      ctx.font = 'bold 14px Inter, sans-serif';
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.fillText(ball.value.toString(), p.x, p.y);
    });

    projectilesRef.current.forEach((proj) => {
      ctx.beginPath();
      ctx.fillStyle = proj.color;
      ctx.shadowBlur = 10;
      ctx.shadowColor = '#fff';
      ctx.arc(proj.x, proj.y, 10, 0, Math.PI * 2);
      ctx.fill();
      ctx.shadowBlur = 0;

      ctx.fillStyle = '#000';
      ctx.font = 'bold 10px Inter, sans-serif';
      ctx.fillText(proj.value.toString(), proj.x, proj.y);
    });

    const centerX = canvas.width / 2;
    const centerY = canvas.height / 2;
    ctx.save();
    ctx.translate(centerX, centerY);
    ctx.rotate(shooterAngleRef.current);

    ctx.fillStyle = '#333';
    ctx.beginPath();
    ctx.roundRect(-20, -15, 60, 30, 8);
    ctx.fill();

    ctx.fillStyle = '#06b6d4';
    ctx.fillRect(35, -5, 5, 10);
    ctx.restore();

    ctx.beginPath();
    ctx.fillStyle = '#1e293b';
    ctx.strokeStyle = '#06b6d4';
    ctx.lineWidth = 3;
    ctx.arc(centerX, centerY, 35, 0, Math.PI * 2);
    ctx.fill();
    ctx.stroke();

    ctx.fillStyle = '#fff';
    ctx.font = 'bold 24px Inter, sans-serif';
    ctx.fillText(currentBallValueRef.current.toString(), centerX, centerY);

    ctx.font = '12px Inter, sans-serif';
    ctx.fillStyle = 'rgba(255,255,255,0.6)';
    ctx.fillText('SIGUIENTE: ' + nextBallValueRef.current.toString(), centerX, centerY + 55);

  }, [gameState, targetNumber, gameMode]);

  useEffect(() => {
    pathRef.current = generatePath(800, 600);
    if (gameState === 'playing') {
      requestRef.current = requestAnimationFrame(update);
    }
    return () => {
      if (requestRef.current) cancelAnimationFrame(requestRef.current);
    };
  }, [gameState]);

  const startGame = (mode: GameMode) => {
    setGameMode(mode);
    setGameState('playing');
    initLevel(1, mode);
  };

  const restartGame = () => {
    setGameState('playing');
    initLevel(1, gameMode);
  };

  const nextLevel = () => {
    setGameState('playing');
    initLevel(level + 1, gameMode);
  };

  useEffect(() => {
    const stored = localStorage.getItem('zuma_math_highscore');
    if (stored) setHighScore(parseInt(stored));
  }, []);

  useEffect(() => {
    if (score > highScore) {
      setHighScore(score);
      localStorage.setItem('zuma_math_highscore', score.toString());
    }
  }, [score, highScore]);

  return (
    <div className="min-h-screen bg-slate-950 text-white font-sans flex flex-col items-center justify-center overflow-hidden">
      {/* HUD */}
      {gameState === 'playing' && (
        <div className="absolute top-0 left-0 w-full p-6 flex justify-between items-start pointer-events-none z-10">
          <div className="bg-slate-900/80 backdrop-blur-md p-4 rounded-2xl border border-slate-800 shadow-xl">
            <div className="flex items-center gap-3 mb-1">
              <div className="p-2 bg-indigo-500/20 rounded-lg">
                <Target className="w-5 h-5 text-indigo-400" />
              </div>
              <span className="text-slate-400 text-sm font-medium uppercase tracking-wider">Misión</span>
            </div>
            <h2 className="text-2xl font-bold">
              {gameMode === 'multiples' ? 'Múltiplos' : 'Divisores'} de{' '}
              <span className="text-indigo-400 underline decoration-indigo-400/30">{targetNumber}</span>
            </h2>
          </div>

          <div className="flex flex-col items-end gap-3">
            <div className="bg-slate-900/80 backdrop-blur-md p-4 rounded-2xl border border-slate-800 shadow-xl min-w-[140px]">
              <div className="text-slate-400 text-xs font-medium uppercase tracking-widest mb-1 text-right">Puntuación</div>
              <div className="text-3xl font-black text-right tabular-nums text-transparent bg-clip-text bg-gradient-to-r from-cyan-400 to-blue-500">
                {score.toLocaleString()}
              </div>
            </div>
            <div className="bg-slate-900/80 backdrop-blur-md px-4 py-2 rounded-xl border border-slate-800 shadow-xl text-sm text-slate-400 font-bold">
              NIVEL {level}
            </div>
          </div>
        </div>
      )}

      {/* Main Canvas Area */}
      <div className="relative group">
        <canvas
          ref={canvasRef}
          width={800}
          height={600}
          onMouseMove={handleMouseMove}
          onClick={handleShoot}
          className={`rounded-3xl shadow-2xl bg-slate-900 border border-slate-800 transition-opacity duration-500 ${gameState !== 'playing' ? 'opacity-20 grayscale' : 'opacity-100'}`}
        />

        {/* Menu Overlays */}
        {gameState === 'menu' && (
          <div className="absolute inset-0 flex flex-col items-center justify-center bg-slate-950/40 backdrop-blur-sm rounded-3xl p-8 text-center animate-in fade-in zoom-in duration-300">
            <div className="mb-8 p-6 bg-indigo-600 rounded-full shadow-[0_0_50px_rgba(79,70,229,0.5)] animate-pulse">
              <Zap className="w-16 h-16 text-white" />
            </div>
            <h1 className="text-6xl font-black mb-2 tracking-tighter bg-clip-text text-transparent bg-gradient-to-b from-white to-slate-400">
              ZUMA MATEMÁTICO
            </h1>
            <p className="text-slate-400 mb-12 max-w-md text-lg">
              Dispara a los números que cumplan la condición. ¡Limpia la línea antes de que llegue al final!
            </p>

            <div className="grid grid-cols-2 gap-6 w-full max-w-lg">
              <button
                onClick={() => startGame('multiples')}
                className="group relative flex flex-col items-center p-8 bg-slate-900 border border-slate-800 rounded-3xl hover:border-indigo-500 transition-all hover:-translate-y-1 hover:shadow-[0_20px_40px_-15px_rgba(79,70,229,0.3)]"
              >
                <div className="mb-4 p-4 bg-indigo-500/10 rounded-2xl group-hover:bg-indigo-500/20 transition-colors">
                  <Play className="w-8 h-8 text-indigo-400" />
                </div>
                <span className="font-bold text-xl mb-1">Múltiplos</span>
                <span className="text-slate-500 text-sm">Objetivo: N × X</span>
              </button>

              <button
                onClick={() => startGame('divisors')}
                className="group relative flex flex-col items-center p-8 bg-slate-900 border border-slate-800 rounded-3xl hover:border-cyan-500 transition-all hover:-translate-y-1 hover:shadow-[0_20px_40px_-15px_rgba(6,182,212,0.3)]"
              >
                <div className="mb-4 p-4 bg-cyan-500/10 rounded-2xl group-hover:bg-cyan-500/20 transition-colors">
                  <Target className="w-8 h-8 text-cyan-400" />
                </div>
                <span className="font-bold text-xl mb-1">Divisores</span>
                <span className="text-slate-500 text-sm">Objetivo / X = Entero</span>
              </button>
            </div>

            <div className="mt-12 flex items-center gap-2 text-slate-500">
              <Trophy className="w-4 h-4" />
              <span className="text-sm font-medium uppercase tracking-widest">Puntuación Máxima: {highScore}</span>
            </div>
          </div>
        )}

        {gameState === 'gameover' && (
          <div className="absolute inset-0 flex flex-col items-center justify-center bg-slate-950/60 backdrop-blur-md rounded-3xl p-8 text-center animate-in fade-in zoom-in duration-300">
            <div className="mb-6 p-5 bg-rose-500/20 rounded-full border border-rose-500/30">
              <AlertTriangle className="w-12 h-12 text-rose-500" />
            </div>
            <h2 className="text-5xl font-black mb-2 text-white text-center">FIN DEL JUEGO</h2>
            <p className="text-slate-400 mb-8 text-lg">¡Los números llegaron al agujero negro!</p>

            <div className="bg-slate-900/50 p-6 rounded-2xl border border-slate-800 mb-8 w-64">
              <div className="text-slate-500 text-xs uppercase tracking-widest mb-1">Puntuación Final</div>
              <div className="text-4xl font-bold text-indigo-400">{score.toLocaleString()}</div>
            </div>

            <div className="flex gap-4">
              <button
                onClick={restartGame}
                className="flex items-center gap-2 px-8 py-4 bg-indigo-600 hover:bg-indigo-500 rounded-2xl font-bold text-white transition-all hover:scale-105"
              >
                <RotateCcw className="w-5 h-5" />
                Reintentar
              </button>
              <button
                onClick={() => setGameState('menu')}
                className="flex items-center gap-2 px-8 py-4 bg-slate-800 hover:bg-slate-700 rounded-2xl font-bold text-white transition-all"
              >
                <Home className="w-5 h-5" />
                Menú Principal
              </button>
            </div>
          </div>
        )}

        {gameState === 'victory' && (
          <div className="absolute inset-0 flex flex-col items-center justify-center bg-indigo-950/40 backdrop-blur-md rounded-3xl p-8 text-center animate-in fade-in zoom-in duration-300">
            <div className="mb-6 p-5 bg-emerald-500/20 rounded-full border border-emerald-500/30">
              <Trophy className="w-16 h-16 text-emerald-500" />
            </div>
            <h2 className="text-5xl font-black mb-2 text-white uppercase tracking-tight">¡Nivel Completado!</h2>
            <p className="text-slate-300 mb-8 text-lg">Has eliminado todas las anomalías matemáticas.</p>

            <div className="flex flex-col items-center bg-slate-900/80 p-6 rounded-3xl border border-indigo-500/30 mb-10 w-80 shadow-2xl">
              <div className="text-indigo-400 text-xs uppercase tracking-widest mb-1 font-bold">Puntos Extra</div>
              <div className="text-5xl font-black text-white mb-4">+500</div>
              <div className="w-full h-px bg-slate-800 mb-4"></div>
              <div className="text-slate-400 text-xs uppercase tracking-widest mb-1">Puntuación Total</div>
              <div className="text-3xl font-bold text-transparent bg-clip-text bg-gradient-to-r from-emerald-400 to-cyan-400">
                {(score + 500).toLocaleString()}
              </div>
            </div>

            <div className="flex gap-4">
              <button
                onClick={nextLevel}
                className="flex items-center gap-2 px-10 py-5 bg-emerald-600 hover:bg-emerald-500 rounded-2xl font-black text-xl text-white transition-all hover:scale-105 shadow-[0_0_30px_rgba(16,185,129,0.3)]"
              >
                <Play className="w-6 h-6 fill-current" />
                Siguiente Nivel
              </button>
              <button
                onClick={() => setGameState('menu')}
                className="flex items-center gap-2 px-8 py-5 bg-slate-800 hover:bg-slate-700 rounded-2xl font-bold text-white transition-all"
              >
                <Home className="w-5 h-5" />
                Menú
              </button>
            </div>
          </div>
        )}
      </div>

      {/* Footer Info */}
      <div className="mt-8 flex flex-wrap justify-center items-center gap-8 text-slate-500 text-sm font-medium uppercase tracking-widest px-4 text-center">
        <div className="flex items-center gap-2">
          <HelpCircle className="w-4 h-4 text-indigo-400" />
          <span>Apunta con el Ratón, Clic para disparar</span>
        </div>
        <div className="flex items-center gap-2">
          <Zap className="w-4 h-4 text-amber-400" />
          <span>Combina disparo y bola para eliminar cadenas</span>
        </div>
      </div>

      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;700;900&display=swap');
        body { margin: 0; background: #020617; font-family: 'Inter', sans-serif; cursor: crosshair; }
        canvas { touch-action: none; cursor: crosshair; }
        .animate-pulse-slow { animation: pulse 4s cubic-bezier(0.4, 0, 0.6, 1) infinite; }
        @keyframes pulse { 0%, 100% { opacity: 1; } 50% { opacity: .7; } }
      `}</style>
    </div>
  );
};

// Render
const rootElement = document.getElementById('root');
if (rootElement) {
  createRoot(rootElement).render(<ZumaMathGame />);
