import React, { useState, useEffect, useRef, useCallback } from 'react';
import { createRoot } from 'react-dom/client';
import { Target, Zap, Play, RotateCcw, Home, HelpCircle, Trophy, AlertTriangle } from 'lucide-react';

// --- Constants & Types ---

type GameMode = 'multiples' | 'divisors';
type GameState = 'menu' | 'playing' | 'gameover' | 'victory';

interface Point {
  x: number;
  y: number;
}

interface Ball {
  id: number;
  value: number;
  pos: number; // 0 to 1 along the path
  color: string;
}

interface Projectile {
  x: number;
  y: number;
  vx: number;
  vy: number;
  value: number;
  color: string;
}

interface Effect {
  type: 'particle' | 'text';
  x: number;
  y: number;
  vx?: number;
  vy?: number;
  life: number;
  maxLife: number;
  text?: string;
  color: string;
  size?: number;
}

const COLORS = [
  '#f43f5e', // rose
  '#06b6d4', // cyan
  '#8b5cf6', // violet
  '#10b981', // emerald
  '#f59e0b', // amber
];

const BALL_RADIUS = 20;
const PROJECTILE_SPEED = 12;
const PATH_SAMPLES = 1000;
const INITIAL_SPEED = 0.0002;
const SPEED_INCREMENT = 0.00005;

// --- Utility Functions ---

const getRandomInt = (min: number, max: number) => Math.floor(Math.random() * (max - min + 1)) + min;

const getConditionMatch = (val: number, target: number, mode: GameMode): boolean => {
  if (mode === 'multiples') {
    return val % target === 0;
  } else {
    return val !== 0 && target % val === 0;
  }
};

const generatePath = (width: number, height: number): Point[] => {
  const points: Point[] = [];
  const centerX = width / 2;
  const centerY = height / 2;
  const maxRadius = Math.min(width, height) * 0.45;
  const loops = 3;

  for (let i = 0; i <= PATH_SAMPLES; i++) {
    const t = i / PATH_SAMPLES;
    const angle = t * Math.PI * 2 * loops;
    const radius = maxRadius * (1 - t * 0.8);
    points.push({
      x: centerX + Math.cos(angle) * radius,
      y: centerY + Math.sin(angle) * radius,
    });
  }
  return points;
};

// --- Main Component ---

const ZumaMathGame = () => {
  const [gameState, setGameState] = useState<GameState>('menu');
  const [gameMode, setGameMode] = useState<GameMode>('multiples');
  const [targetNumber, setTargetNumber] = useState<number>(5);
  const [score, setScore] = useState<number>(0);
  const [level, setLevel] = useState<number>(1);
  const [highScore, setHighScore] = useState<number>(0);

  const canvasRef = useRef<HTMLCanvasElement>(null);
  const requestRef = useRef<number>();
  const pathRef = useRef<Point[]>([]);
  const ballsRef = useRef<Ball[]>([]);
  const projectilesRef = useRef<Projectile[]>([]);
  const effectsRef = useRef<Effect[]>([]);
  const shooterAngleRef = useRef<number>(0);
  const nextBallValueRef = useRef<number>(5);
  const currentBallValueRef = useRef<number>(5);
  const mousePosRef = useRef<Point>({ x: 0, y: 0 });
  const gameSpeedRef = useRef<number>(INITIAL_SPEED);
  const lastTimeRef = useRef<number>(0);
  const ballCounterRef = useRef<number>(0);
  const screenShakeRef = useRef<number>(0);

  const spawnParticles = (x: number, y: number, color: string, count = 8) => {
    for (let i = 0; i < count; i++) {
      const angle = Math.random() * Math.PI * 2;
      const speed = Math.random() * 4 + 2;
      effectsRef.current.push({
        type: 'particle',
        x,
        y,
        vx: Math.cos(angle) * speed,
        vy: Math.sin(angle) * speed,
        life: 1,
        maxLife: 1,
        color,
        size: Math.random() * 4 + 2,
      });
    }
  };

  const spawnText = (x: number, y: number, text: string, color: string, size = 20) => {
    effectsRef.current.push({
      type: 'text',
      x,
      y,
      vy: -1.5,
      life: 1,
      maxLife: 1,
      text,
      color,
      size,
    });
  };

  const initLevel = (lvl: number, mode: GameMode) => {
    let target = 0;
    if (mode === 'multiples') {
      target = getRandomInt(2, 9);
    } else {
      const choices = [12, 16, 18, 20, 24, 30, 36, 40, 48, 60];
      target = choices[getRandomInt(0, choices.length - 1)];
    }

    setTargetNumber(target);
    setScore(0);
    setLevel(lvl);
    gameSpeedRef.current = INITIAL_SPEED + (lvl - 1) * SPEED_INCREMENT;
    projectilesRef.current = [];
    effectsRef.current = [];
    ballCounterRef.current = 0;

    const initialBalls: Ball[] = [];
    for (let i = 0; i < 10 + lvl * 2; i++) {
      initialBalls.push(generateRandomBall(-i * 0.035, target, mode));
    }
    ballsRef.current = initialBalls;

    currentBallValueRef.current = generateFairBallValue(target, mode);
    nextBallValueRef.current = generateFairBallValue(target, mode);
  };

  const generateRandomBall = (pos: number, target: number, mode: GameMode): Ball => {
    const value = generateFairBallValue(target, mode);
    return {
      id: ballCounterRef.current++,
      value,
      pos,
      color: COLORS[getRandomInt(0, COLORS.length - 1)],
    };
  };

  const generateFairBallValue = (target: number, mode: GameMode): number => {
    const isMatch = Math.random() > 0.4;
    if (mode === 'multiples') {
      if (isMatch) return target * getRandomInt(1, 10);
      return getRandomInt(1, 50);
    } else {
      if (isMatch) {
        const divisors = [];
        for (let i = 1; i <= target; i++) if (target % i === 0) divisors.push(i);
        return divisors[getRandomInt(0, divisors.length - 1)];
      }
      return getRandomInt(1, target + 10);
    }
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const rect = canvas.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;
    mousePosRef.current = { x, y };

    const centerX = canvas.width / 2;
    const centerY = canvas.height / 2;
    shooterAngleRef.current = Math.atan2(y - centerY, x - centerX);
  };

  const handleShoot = () => {
    if (gameState !== 'playing') return;
    const canvas = canvasRef.current;
    if (!canvas) return;

    const centerX = canvas.width / 2;
    const centerY = canvas.height / 2;
    const angle = shooterAngleRef.current;

    projectilesRef.current.push({
      x: centerX + Math.cos(angle) * 40,
      y: centerY + Math.sin(angle) * 40,
      vx: Math.cos(angle) * PROJECTILE_SPEED,
      vy: Math.sin(angle) * PROJECTILE_SPEED,
      value: currentBallValueRef.current,
      color: '#ffffff',
    });

    currentBallValueRef.current = nextBallValueRef.current;
    nextBallValueRef.current = generateFairBallValue(targetNumber, gameMode);
  };

  const update = (time: number) => {
    if (gameState !== 'playing') return;

    const deltaTime = time - lastTimeRef.current;
    lastTimeRef.current = time;

    // 1. Move balls along path
    let gameOver = false;
    ballsRef.current.forEach((ball) => {
      ball.pos += gameSpeedRef.current;
      if (ball.pos >= 1) gameOver = true;
    });

    if (gameOver) {
      setGameState('gameover');
      return;
    }

    // 2. Move projectiles and detect collisions
    const path = pathRef.current;
    projectilesRef.current = projectilesRef.current.filter((proj) => {
      proj.x += proj.vx;
      proj.y += proj.vy;

      if (proj.x < 0 || proj.x > 800 || proj.y < 0 || proj.y > 600) return false;

      for (let i = 0; i < ballsRef.current.length; i++) {
        const ball = ballsRef.current[i];
        if (ball.pos < 0) continue;

        const pathIdx = Math.floor(ball.pos * (PATH_SAMPLES - 1));
        const ballPoint = path[pathIdx];
        const dist = Math.sqrt((proj.x - ballPoint.x) ** 2 + (proj.y - ballPoint.y) ** 2);

        if (dist < BALL_RADIUS * 1.5) {
          handleHit(ball, proj.value, i);
          return false;
        }
      }
      return true;
    });

    // 3. Update effects
    effectsRef.current = effectsRef.current.filter(eff => {
      eff.life -= 0.02;
      eff.x += (eff.vx || 0);
      eff.y += (eff.vy || 0);
      return eff.life > 0;
    });

    // 4. Update screen shake
    if (screenShakeRef.current > 0) {
      screenShakeRef.current -= 0.5;
    }

    // 5. Check for victory
    if (ballsRef.current.length === 0) {
      setGameState('victory');
    }

    draw();
    requestRef.current = requestAnimationFrame(update);
  };

  const handleHit = (hitBall: Ball, shotValue: number, ballIndex: number) => {
    const shotMatches = getConditionMatch(shotValue, targetNumber, gameMode);
    const hitMatches = getConditionMatch(hitBall.value, targetNumber, gameMode);

    const pathIdx = Math.floor(hitBall.pos * (PATH_SAMPLES - 1));
    const hitPoint = pathRef.current[pathIdx];

    if (shotMatches && hitMatches) {
      let toRemoveIndices = [ballIndex];
      for (let j = ballIndex + 1; j < ballsRef.current.length; j++) {
        if (getConditionMatch(ballsRef.current[j].value, targetNumber, gameMode)) {
          toRemoveIndices.push(j);
        } else break;
      }
      for (let j = ballIndex - 1; j >= 0; j--) {
        if (getConditionMatch(ballsRef.current[j].value, targetNumber, gameMode)) {
          toRemoveIndices.push(j);
        } else break;
      }

      const points = toRemoveIndices.length * 100;
      setScore(prev => prev + points);

      // Effects for each removed ball
      toRemoveIndices.forEach(idx => {
        const b = ballsRef.current[idx];
        const pIdx = Math.floor(b.pos * (PATH_SAMPLES - 1));
        const p = pathRef.current[pIdx];
        spawnParticles(p.x, p.y, b.color, 12);
      });

      // Combo Text
      if (toRemoveIndices.length >= 3) {
        spawnText(hitPoint.x, hitPoint.y - 30, `¡COMBO x${toRemoveIndices.length}!`, '#fcd34d', 28);
        screenShakeRef.current = 8;
      } else {
        spawnText(hitPoint.x, hitPoint.y - 20, `+${points}`, '#fff', 20);
        screenShakeRef.current = 3;
      }

      ballsRef.current = ballsRef.current.filter((_, idx) => !toRemoveIndices.includes(idx));
    } else {
      // Failed to match
      const newBall: Ball = {
        id: ballCounterRef.current++,
        value: shotValue,
        pos: hitBall.pos - 0.03,
        color: COLORS[getRandomInt(0, COLORS.length - 1)],
      };

      const newBalls = [...ballsRef.current];
      newBalls.splice(ballIndex, 0, newBall);
      ballsRef.current = newBalls;

      // Hit flash
      spawnParticles(hitPoint.x, hitPoint.y, '#ffffff', 4);

      for (let i = 1; i < ballsRef.current.length; i++) {
        if (ballsRef.current[i].pos > ballsRef.current[i-1].pos - 0.035) {
          ballsRef.current[i].pos = ballsRef.current[i-1].pos - 0.035;
        }
      }
    }
  };

  const draw = useCallback(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    ctx.save();
    if (screenShakeRef.current > 0) {
      const shakeX = (Math.random() - 0.5) * screenShakeRef.current;
      const shakeY = (Math.random() - 0.5) * screenShakeRef.current;
      ctx.translate(shakeX, shakeY);
    }

    ctx.clearRect(-10, -10, canvas.width + 20, canvas.height + 20);

    // Path
    ctx.beginPath();
    ctx.strokeStyle = 'rgba(255, 255, 255, 0.08)';
    ctx.lineWidth = 40;
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';
    pathRef.current.forEach((p, i) => {
      if (i === 0) ctx.moveTo(p.x, p.y);
      else ctx.lineTo(p.x, p.y);
    });
    ctx.stroke();

    // Black Hole
    const endPoint = pathRef.current[PATH_SAMPLES];
    ctx.beginPath();
    ctx.fillStyle = '#000';
    ctx.shadowBlur = 15;
    ctx.shadowColor = '#f00';
    ctx.arc(endPoint.x, endPoint.y, 25 + Math.sin(Date.now() / 200) * 5, 0, Math.PI * 2);
    ctx.fill();
    ctx.shadowBlur = 0;

    // Balls
    ballsRef.current.forEach((ball) => {
      if (ball.pos < 0 || ball.pos > 1) return;
      const pIdx = Math.floor(ball.pos * (PATH_SAMPLES - 1));
      const p = pathRef.current[pIdx];

      const isMatch = getConditionMatch(ball.value, targetNumber, gameMode);
      if (isMatch) {
        ctx.shadowBlur = 20;
        ctx.shadowColor = ball.color;
      }

      ctx.beginPath();
      ctx.fillStyle = ball.color;
      ctx.arc(p.x, p.y, BALL_RADIUS, 0, Math.PI * 2);
      ctx.fill();

      ctx.shadowBlur = 0;
      ctx.fillStyle = '#fff';
      ctx.font = 'bold 15px Inter, sans-serif';
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.fillText(ball.value.toString(), p.x, p.y);
    });

    // Projectiles
    projectilesRef.current.forEach((proj) => {
      ctx.beginPath();
      ctx.fillStyle = proj.color;
      ctx.shadowBlur = 15;
      ctx.shadowColor = '#fff';
      ctx.arc(proj.x, proj.y, 11, 0, Math.PI * 2);
      ctx.fill();
      ctx.shadowBlur = 0;

      ctx.fillStyle = '#000';
      ctx.font = 'bold 12px Inter, sans-serif';
      ctx.fillText(proj.value.toString(), proj.x, proj.y);
    });

    // Effects
    effectsRef.current.forEach(eff => {
      ctx.globalAlpha = eff.life;
      if (eff.type === 'particle') {
        ctx.beginPath();
        ctx.fillStyle = eff.color;
        ctx.arc(eff.x, eff.y, eff.size || 3, 0, Math.PI * 2);
        ctx.fill();
      } else {
        ctx.fillStyle = eff.color;
        ctx.shadowBlur = 5;
        ctx.shadowColor = 'rgba(0,0,0,0.5)';
        ctx.font = `bold ${eff.size}px Inter, sans-serif`;
        ctx.fillText(eff.text || '', eff.x, eff.y);
        ctx.shadowBlur = 0;
      }
    });
    ctx.globalAlpha = 1;

    // Shooter
    const centerX = canvas.width / 2;
    const centerY = canvas.height / 2;
    ctx.save();
    ctx.translate(centerX, centerY);
    ctx.rotate(shooterAngleRef.current);
    ctx.fillStyle = '#334155';
    ctx.beginPath();
    ctx.roundRect(-22, -18, 65, 36, 10);
    ctx.fill();
    ctx.fillStyle = '#0ea5e9';
    ctx.fillRect(38, -6, 6, 12);
    ctx.restore();

    ctx.beginPath();
    ctx.fillStyle = '#0f172a';
    ctx.strokeStyle = '#0ea5e9';
    ctx.lineWidth = 4;
    ctx.arc(centerX, centerY, 38, 0, Math.PI * 2);
    ctx.fill();
    ctx.stroke();

    ctx.fillStyle = '#fff';
    ctx.font = 'bold 26px Inter, sans-serif';
    ctx.fillText(currentBallValueRef.current.toString(), centerX, centerY);

    ctx.font = 'bold 13px Inter, sans-serif';
    ctx.fillStyle = 'rgba(255,255,255,0.7)';
    ctx.fillText('SIGUIENTE: ' + nextBallValueRef.current.toString(), centerX, centerY + 58);

    ctx.restore();
  }, [gameState, targetNumber, gameMode]);

  useEffect(() => {
    pathRef.current = generatePath(800, 600);
    if (gameState === 'playing') {
      requestRef.current = requestAnimationFrame(update);
    }
    return () => {
      if (requestRef.current) cancelAnimationFrame(requestRef.current);
    };
  }, [gameState]);

  const startGame = (mode: GameMode) => {
    setGameMode(mode);
    setGameState('playing');
    initLevel(1, mode);
  };

  const restartGame = () => {
    setGameState('playing');
    initLevel(1, gameMode);
  };

  const nextLevel = () => {
    setGameState('playing');
    initLevel(level + 1, gameMode);
  };

  useEffect(() => {
    const stored = localStorage.getItem('zuma_math_highscore');
    if (stored) setHighScore(parseInt(stored));
  }, []);

  useEffect(() => {
    if (score > highScore) {
      setHighScore(score);
      localStorage.setItem('zuma_math_highscore', score.toString());
    }
  }, [score, highScore]);

  return (
    <div className="min-h-screen bg-slate-950 text-white font-sans flex flex-col items-center justify-center overflow-hidden selection:bg-indigo-500/30">
      {/* HUD */}
      {gameState === 'playing' && (
        <div className="absolute top-0 left-0 w-full p-6 flex justify-between items-start pointer-events-none z-10">
          <div className="bg-slate-900/90 backdrop-blur-xl p-5 rounded-3xl border border-white/10 shadow-2xl ring-1 ring-white/5">
            <div className="flex items-center gap-3 mb-1">
              <div className="p-2 bg-indigo-500/20 rounded-xl">
                <Target className="w-5 h-5 text-indigo-400" />
              </div>
              <span className="text-slate-400 text-xs font-bold uppercase tracking-[0.2em]">Misión de Nivel</span>
            </div>
            <h2 className="text-2xl font-black tracking-tight">
              {gameMode === 'multiples' ? 'Múltiplos' : 'Divisores'} de{' '}
              <span className="text-indigo-400 px-2 py-0.5 bg-indigo-400/10 rounded-lg">{targetNumber}</span>
            </h2>
          </div>

          <div className="flex flex-col items-end gap-3">
            <div className="bg-slate-900/90 backdrop-blur-xl p-5 rounded-3xl border border-white/10 shadow-2xl ring-1 ring-white/5 min-w-[160px]">
              <div className="text-slate-400 text-[10px] font-bold uppercase tracking-[0.2em] mb-1 text-right">Puntuación</div>
              <div className="text-4xl font-black text-right tabular-nums text-transparent bg-clip-text bg-gradient-to-br from-white to-slate-500">
                {score.toLocaleString()}
              </div>
            </div>
            <div className="bg-indigo-600 px-5 py-2 rounded-2xl border border-white/10 shadow-xl text-sm font-black tracking-widest uppercase">
              NIVEL {level}
            </div>
          </div>
        </div>
      )}

      {/* Main Canvas Area */}
      <div className="relative">
        <canvas
          ref={canvasRef}
          width={800}
          height={600}
          onMouseMove={handleMouseMove}
          onClick={handleShoot}
          className={`rounded-[2.5rem] shadow-[0_0_100px_rgba(0,0,0,0.5)] bg-slate-900/50 border border-white/5 transition-all duration-700 ${gameState !== 'playing' ? 'opacity-30 blur-sm scale-95 pointer-events-none' : 'opacity-100 scale-100'}`}
        />

        {/* Menu Overlays */}
        {gameState === 'menu' && (
          <div className="absolute inset-0 flex flex-col items-center justify-center bg-slate-950/40 backdrop-blur-sm rounded-[2.5rem] p-8 text-center animate-in fade-in zoom-in duration-500">
            <div className="mb-8 p-8 bg-indigo-600 rounded-[2rem] shadow-[0_0_60px_rgba(79,70,229,0.4)] animate-bounce-slow">
              <Zap className="w-20 h-20 text-white fill-current" />
            </div>
            <h1 className="text-7xl font-black mb-4 tracking-tighter bg-clip-text text-transparent bg-gradient-to-b from-white via-white to-slate-500">
              MATH ZUMA
            </h1>
            <p className="text-slate-400 mb-12 max-w-lg text-xl font-medium leading-relaxed">
              El reto definitivo de agilidad mental. Elimina las esferas numéricas antes de que el vacío las consuma.
            </p>

            <div className="grid grid-cols-2 gap-8 w-full max-w-xl">
              <button
                onClick={() => startGame('multiples')}
                className="group relative flex flex-col items-center p-10 bg-slate-900/80 backdrop-blur-md border border-white/5 rounded-[2rem] hover:border-indigo-500 transition-all hover:-translate-y-2 hover:shadow-[0_30px_60px_-15px_rgba(79,70,229,0.4)]"
              >
                <div className="mb-5 p-5 bg-indigo-500/10 rounded-2xl group-hover:bg-indigo-500/20 transition-colors">
                  <Play className="w-10 h-10 text-indigo-400 fill-current" />
                </div>
                <span className="font-black text-2xl mb-2 tracking-tight">Múltiplos</span>
                <span className="text-slate-500 text-xs font-bold uppercase tracking-widest">N × 1, 2, 3...</span>
              </button>

              <button
                onClick={() => startGame('divisors')}
                className="group relative flex flex-col items-center p-10 bg-slate-900/80 backdrop-blur-md border border-white/5 rounded-[2rem] hover:border-cyan-500 transition-all hover:-translate-y-2 hover:shadow-[0_30px_60px_-15px_rgba(6,182,212,0.4)]"
              >
                <div className="mb-5 p-5 bg-cyan-500/10 rounded-2xl group-hover:bg-cyan-500/20 transition-colors">
                  <Target className="w-10 h-10 text-cyan-400" />
                </div>
                <span className="font-black text-2xl mb-2 tracking-tight">Divisores</span>
                <span className="text-slate-500 text-xs font-bold uppercase tracking-widest">N / X = Entero</span>
              </button>
            </div>

            <div className="mt-14 flex items-center gap-3 text-slate-500 px-6 py-3 bg-white/5 rounded-full border border-white/5">
              <Trophy className="w-5 h-5 text-amber-500" />
              <span className="text-sm font-black uppercase tracking-[0.2em]">Record: {highScore}</span>
            </div>
          </div>
        )}

        {gameState === 'gameover' && (
          <div className="absolute inset-0 flex flex-col items-center justify-center bg-slate-950/80 backdrop-blur-xl rounded-[2.5rem] p-8 text-center animate-in fade-in zoom-in duration-500">
            <div className="mb-6 p-6 bg-rose-500/20 rounded-full border border-rose-500/30">
              <AlertTriangle className="w-16 h-16 text-rose-500" />
            </div>
            <h2 className="text-6xl font-black mb-2 text-white tracking-tighter">COLAPSO TOTAL</h2>
            <p className="text-slate-400 mb-10 text-xl font-medium">¡El agujero negro ha consumido los cálculos!</p>

            <div className="bg-slate-900/80 p-8 rounded-[2rem] border border-white/10 mb-10 w-72 shadow-2xl">
              <div className="text-slate-500 text-xs font-bold uppercase tracking-widest mb-2">Final</div>
              <div className="text-5xl font-black text-indigo-400 tabular-nums">{score.toLocaleString()}</div>
            </div>

            <div className="flex gap-6">
              <button
                onClick={restartGame}
                className="flex items-center gap-3 px-10 py-5 bg-indigo-600 hover:bg-indigo-500 rounded-2xl font-black text-white transition-all hover:scale-105 shadow-[0_20px_40px_-10px_rgba(79,70,229,0.4)]"
              >
                <RotateCcw className="w-6 h-6" />
                REINTENTAR
              </button>
              <button
                onClick={() => setGameState('menu')}
                className="flex items-center gap-3 px-10 py-5 bg-slate-800 hover:bg-slate-700 rounded-2xl font-black text-white transition-all"
              >
                <Home className="w-6 h-6" />
                MENÚ
              </button>
            </div>
          </div>
        )}

        {gameState === 'victory' && (
          <div className="absolute inset-0 flex flex-col items-center justify-center bg-indigo-950/60 backdrop-blur-xl rounded-[2.5rem] p-8 text-center animate-in fade-in zoom-in duration-500">
            <div className="mb-8 p-8 bg-emerald-500/20 rounded-[2rem] border border-emerald-500/30 shadow-[0_0_50px_rgba(16,185,129,0.3)]">
              <Trophy className="w-20 h-20 text-emerald-400" />
            </div>
            <h2 className="text-7xl font-black mb-4 text-white uppercase tracking-tighter">¡LOGRADO!</h2>
            <p className="text-slate-300 mb-10 text-xl font-medium">Anomalías matemáticas neutralizadas con éxito.</p>

            <div className="flex flex-col items-center bg-slate-900/90 p-8 rounded-[2rem] border border-emerald-500/20 mb-12 w-80 shadow-3xl ring-1 ring-white/5">
              <div className="text-emerald-400 text-xs font-black uppercase tracking-[0.2em] mb-2">Bonus de Nivel</div>
              <div className="text-6xl font-black text-white mb-6 animate-pulse">+500</div>
              <div className="w-full h-px bg-white/5 mb-6"></div>
              <div className="text-slate-400 text-xs font-black uppercase tracking-[0.2em] mb-2">Total Acumulado</div>
              <div className="text-4xl font-black text-transparent bg-clip-text bg-gradient-to-r from-emerald-400 to-cyan-400">
                {(score + 500).toLocaleString()}
              </div>
            </div>

            <div className="flex gap-6">
              <button
                onClick={nextLevel}
                className="flex items-center gap-4 px-12 py-6 bg-emerald-600 hover:bg-emerald-500 rounded-2xl font-black text-2xl text-white transition-all hover:scale-105 shadow-[0_25px_50px_-10px_rgba(16,185,129,0.5)]"
              >
                <Play className="w-8 h-8 fill-current" />
                SIGUIENTE
              </button>
              <button
                onClick={() => setGameState('menu')}
                className="flex items-center gap-3 px-10 py-6 bg-slate-800 hover:bg-slate-700 rounded-2xl font-black text-white transition-all"
              >
                <Home className="w-6 h-6" />
              </button>
            </div>
          </div>
        )}
      </div>

      {/* Footer Info */}
      <div className="mt-12 flex flex-wrap justify-center items-center gap-12 text-slate-500 text-xs font-black uppercase tracking-[0.3em] px-4 text-center opacity-60">
        <div className="flex items-center gap-3">
          <HelpCircle className="w-5 h-5 text-indigo-500" />
          <span>Raton para apuntar / Clic para disparar</span>
        </div>
        <div className="flex items-center gap-3">
          <Zap className="w-5 h-5 text-amber-500" />
          <span>Combina y genera combos explosivos</span>
        </div>
      </div>

      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;700;900&display=swap');
        body { 
          margin: 0; 
          background: #020617; 
          font-family: 'Inter', sans-serif; 
          cursor: crosshair; 
          user-select: none;
        }
        canvas { touch-action: none; cursor: crosshair; }
        .animate-bounce-slow { animation: bounce 3s infinite; }
        @keyframes bounce {
          0%, 100% { transform: translateY(-5%); animation-timing-function: cubic-bezier(0.8, 0, 1, 1); }
          50% { transform: translateY(0); animation-timing-function: cubic-bezier(0, 0, 0.2, 1); }
        }
      `}</style>
    </div>
  );
};

// Render
const rootElement = document.getElementById('root');
if (rootElement) {
  createRoot(rootElement).render(<ZumaMathGame />);
}

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { createRoot } from 'react-dom/client';
import { Target, Zap, Play, RotateCcw, Home, HelpCircle, Trophy, AlertTriangle, BookOpen, ChevronRight, ChevronLeft, X } from 'lucide-react';

// --- Constants & Types ---

type GameMode = 'multiples' | 'divisors';
type GameState = 'menu' | 'playing' | 'gameover' | 'victory' | 'tutorial';

interface Point {
  x: number;
  y: number;
}

interface Ball {
  id: number;
  value: number;
  pos: number; // 0 to 1 along the path
  color: string;
}

interface Projectile {
  x: number;
  y: number;
  vx: number;
  vy: number;
  value: number;
  color: string;
}

interface Effect {
  type: 'particle' | 'text';
  x: number;
  y: number;
  vx?: number;
  vy?: number;
  life: number;
  maxLife: number;
  text?: string;
  color: string;
  size?: number;
}

const COLORS = [
  '#f43f5e', // rose
  '#06b6d4', // cyan
  '#8b5cf6', // violet
  '#10b981', // emerald
  '#f59e0b', // amber
];

const BALL_RADIUS = 20;
const PROJECTILE_SPEED = 12;
const PATH_SAMPLES = 1000;
const INITIAL_SPEED = 0.0002;
const SPEED_INCREMENT = 0.00005;

// --- Utility Functions ---

const getRandomInt = (min: number, max: number) => Math.floor(Math.random() * (max - min + 1)) + min;

const getConditionMatch = (val: number, target: number, mode: GameMode): boolean => {
  if (mode === 'multiples') {
    return val % target === 0;
  } else {
    return val !== 0 && target % val === 0;
  }
};

const generatePath = (width: number, height: number): Point[] => {
  const points: Point[] = [];
  const centerX = width / 2;
  const centerY = height / 2;
  const maxRadius = Math.min(width, height) * 0.45;
  const loops = 3;

  for (let i = 0; i <= PATH_SAMPLES; i++) {
    const t = i / PATH_SAMPLES;
    const angle = t * Math.PI * 2 * loops;
    const radius = maxRadius * (1 - t * 0.8);
    points.push({
      x: centerX + Math.cos(angle) * radius,
      y: centerY + Math.sin(angle) * radius,
    });
  }
  return points;
};

// --- Main Component ---

const ZumaMathGame = () => {
  const [gameState, setGameState] = useState<GameState>('menu');
  const [gameMode, setGameMode] = useState<GameMode>('multiples');
  const [targetNumber, setTargetNumber] = useState<number>(5);
  const [score, setScore] = useState<number>(0);
  const [level, setLevel] = useState<number>(1);
  const [highScore, setHighScore] = useState<number>(0);
  const [tutorialStep, setTutorialStep] = useState(0);

  const canvasRef = useRef<HTMLCanvasElement>(null);
  const requestRef = useRef<number>();
  const pathRef = useRef<Point[]>([]);
  const ballsRef = useRef<Ball[]>([]);
  const projectilesRef = useRef<Projectile[]>([]);
  const effectsRef = useRef<Effect[]>([]);
  const shooterAngleRef = useRef<number>(0);
  const nextBallValueRef = useRef<number>(5);
  const currentBallValueRef = useRef<number>(5);
  const mousePosRef = useRef<Point>({ x: 0, y: 0 });
  const gameSpeedRef = useRef<number>(INITIAL_SPEED);
  const lastTimeRef = useRef<number>(0);
  const ballCounterRef = useRef<number>(0);
  const screenShakeRef = useRef<number>(0);

  const spawnParticles = (x: number, y: number, color: string, count = 8) => {
    for (let i = 0; i < count; i++) {
      const angle = Math.random() * Math.PI * 2;
      const speed = Math.random() * 4 + 2;
      effectsRef.current.push({
        type: 'particle',
        x,
        y,
        vx: Math.cos(angle) * speed,
        vy: Math.sin(angle) * speed,
        life: 1,
        maxLife: 1,
        color,
        size: Math.random() * 4 + 2,
      });
    }
  };

  const spawnText = (x: number, y: number, text: string, color: string, size = 20) => {
    effectsRef.current.push({
      type: 'text',
      x,
      y,
      vy: -1.5,
      life: 1,
      maxLife: 1,
      text,
      color,
      size,
    });
  };

  const initLevel = (lvl: number, mode: GameMode) => {
    let target = 0;
    if (mode === 'multiples') {
      target = getRandomInt(2, 9);
    } else {
      const choices = [12, 16, 18, 20, 24, 30, 36, 40, 48, 60];
      target = choices[getRandomInt(0, choices.length - 1)];
    }

    setTargetNumber(target);
    setScore(0);
    setLevel(lvl);
    gameSpeedRef.current = INITIAL_SPEED + (lvl - 1) * SPEED_INCREMENT;
    projectilesRef.current = [];
    effectsRef.current = [];
    ballCounterRef.current = 0;

    const initialBalls: Ball[] = [];
    for (let i = 0; i < 10 + lvl * 2; i++) {
      initialBalls.push(generateRandomBall(-i * 0.035, target, mode));
    }
    ballsRef.current = initialBalls;

    currentBallValueRef.current = generateFairBallValue(target, mode);
    nextBallValueRef.current = generateFairBallValue(target, mode);
  };

  const generateRandomBall = (pos: number, target: number, mode: GameMode): Ball => {
    const value = generateFairBallValue(target, mode);
    return {
      id: ballCounterRef.current++,
      value,
      pos,
      color: COLORS[getRandomInt(0, COLORS.length - 1)],
    };
  };

  const generateFairBallValue = (target: number, mode: GameMode): number => {
    const isMatch = Math.random() > 0.4;
    if (mode === 'multiples') {
      if (isMatch) return target * getRandomInt(1, 10);
      return getRandomInt(1, 50);
    } else {
      if (isMatch) {
        const divisors = [];
        for (let i = 1; i <= target; i++) if (target % i === 0) divisors.push(i);
        return divisors[getRandomInt(0, divisors.length - 1)];
      }
      return getRandomInt(1, target + 10);
    }
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const rect = canvas.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;
    mousePosRef.current = { x, y };

    const centerX = canvas.width / 2;
    const centerY = canvas.height / 2;
    shooterAngleRef.current = Math.atan2(y - centerY, x - centerX);
  };

  const handleShoot = () => {
    if (gameState !== 'playing') return;
    const canvas = canvasRef.current;
    if (!canvas) return;

    const centerX = canvas.width / 2;
    const centerY = canvas.height / 2;
    const angle = shooterAngleRef.current;

    projectilesRef.current.push({
      x: centerX + Math.cos(angle) * 40,
      y: centerY + Math.sin(angle) * 40,
      vx: Math.cos(angle) * PROJECTILE_SPEED,
      vy: Math.sin(angle) * PROJECTILE_SPEED,
      value: currentBallValueRef.current,
      color: '#ffffff',
    });

    currentBallValueRef.current = nextBallValueRef.current;
    nextBallValueRef.current = generateFairBallValue(targetNumber, gameMode);
  };

  const update = (time: number) => {
    if (gameState !== 'playing') return;

    const deltaTime = time - lastTimeRef.current;
    lastTimeRef.current = time;

    // 1. Move balls along path
    let gameOver = false;
    ballsRef.current.forEach((ball) => {
      ball.pos += gameSpeedRef.current;
      if (ball.pos >= 1) gameOver = true;
    });

    if (gameOver) {
      setGameState('gameover');
      return;
    }

    // 2. Move projectiles and detect collisions
    const path = pathRef.current;
    projectilesRef.current = projectilesRef.current.filter((proj) => {
      proj.x += proj.vx;
      proj.y += proj.vy;

      if (proj.x < 0 || proj.x > 800 || proj.y < 0 || proj.y > 600) return false;

      for (let i = 0; i < ballsRef.current.length; i++) {
        const ball = ballsRef.current[i];
        if (ball.pos < 0) continue;

        const pathIdx = Math.floor(ball.pos * (PATH_SAMPLES - 1));
        const ballPoint = path[pathIdx];
        const dist = Math.sqrt((proj.x - ballPoint.x) ** 2 + (proj.y - ballPoint.y) ** 2);

        if (dist < BALL_RADIUS * 1.5) {
          handleHit(ball, proj.value, i);
          return false;
        }
      }
      return true;
    });

    // 3. Update effects
    effectsRef.current = effectsRef.current.filter(eff => {
      eff.life -= 0.02;
      eff.x += (eff.vx || 0);
      eff.y += (eff.vy || 0);
      return eff.life > 0;
    });

    // 4. Update screen shake
    if (screenShakeRef.current > 0) {
      screenShakeRef.current -= 0.5;
    }

    // 5. Check for victory
    if (ballsRef.current.length === 0) {
      setGameState('victory');
    }

    draw();
    requestRef.current = requestAnimationFrame(update);
  };

  const handleHit = (hitBall: Ball, shotValue: number, ballIndex: number) => {
    const shotMatches = getConditionMatch(shotValue, targetNumber, gameMode);
    const hitMatches = getConditionMatch(hitBall.value, targetNumber, gameMode);

    const pathIdx = Math.floor(hitBall.pos * (PATH_SAMPLES - 1));
    const hitPoint = pathRef.current[pathIdx];

    if (shotMatches && hitMatches) {
      let toRemoveIndices = [ballIndex];
      for (let j = ballIndex + 1; j < ballsRef.current.length; j++) {
        if (getConditionMatch(ballsRef.current[j].value, targetNumber, gameMode)) {
          toRemoveIndices.push(j);
        } else break;
      }
      for (let j = ballIndex - 1; j >= 0; j--) {
        if (getConditionMatch(ballsRef.current[j].value, targetNumber, gameMode)) {
          toRemoveIndices.push(j);
        } else break;
      }

      const points = toRemoveIndices.length * 100;
      setScore(prev => prev + points);

      toRemoveIndices.forEach(idx => {
        const b = ballsRef.current[idx];
        const pIdx = Math.floor(b.pos * (PATH_SAMPLES - 1));
        const p = pathRef.current[pIdx];
        spawnParticles(p.x, p.y, b.color, 12);
      });

      if (toRemoveIndices.length >= 3) {
        spawnText(hitPoint.x, hitPoint.y - 30, `¡COMBO x${toRemoveIndices.length}!`, '#fcd34d', 28);
        screenShakeRef.current = 8;
      } else {
        spawnText(hitPoint.x, hitPoint.y - 20, `+${points}`, '#fff', 20);
        screenShakeRef.current = 3;
      }

      ballsRef.current = ballsRef.current.filter((_, idx) => !toRemoveIndices.includes(idx));
    } else {
      const newBall: Ball = {
        id: ballCounterRef.current++,
        value: shotValue,
        pos: hitBall.pos - 0.03,
        color: COLORS[getRandomInt(0, COLORS.length - 1)],
      };

      const newBalls = [...ballsRef.current];
      newBalls.splice(ballIndex, 0, newBall);
      ballsRef.current = newBalls;

      spawnParticles(hitPoint.x, hitPoint.y, '#ffffff', 4);

      for (let i = 1; i < ballsRef.current.length; i++) {
        if (ballsRef.current[i].pos > ballsRef.current[i-1].pos - 0.035) {
          ballsRef.current[i].pos = ballsRef.current[i-1].pos - 0.035;
        }
      }
    }
  };

  const draw = useCallback(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    ctx.save();
    if (screenShakeRef.current > 0) {
      const shakeX = (Math.random() - 0.5) * screenShakeRef.current;
      const shakeY = (Math.random() - 0.5) * screenShakeRef.current;
      ctx.translate(shakeX, shakeY);
    }

    ctx.clearRect(-10, -10, canvas.width + 20, canvas.height + 20);

    ctx.beginPath();
    ctx.strokeStyle = 'rgba(255, 255, 255, 0.08)';
    ctx.lineWidth = 40;
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';
    pathRef.current.forEach((p, i) => {
      if (i === 0) ctx.moveTo(p.x, p.y);
      else ctx.lineTo(p.x, p.y);
    });
    ctx.stroke();

    const endPoint = pathRef.current[PATH_SAMPLES];
    ctx.beginPath();
    ctx.fillStyle = '#000';
    ctx.shadowBlur = 15;
    ctx.shadowColor = '#f00';
    ctx.arc(endPoint.x, endPoint.y, 25 + Math.sin(Date.now() / 200) * 5, 0, Math.PI * 2);
    ctx.fill();
    ctx.shadowBlur = 0;

    ballsRef.current.forEach((ball) => {
      if (ball.pos < 0 || ball.pos > 1) return;
      const pIdx = Math.floor(ball.pos * (PATH_SAMPLES - 1));
      const p = pathRef.current[pIdx];

      const isMatch = getConditionMatch(ball.value, targetNumber, gameMode);
      if (isMatch) {
        ctx.shadowBlur = 20;
        ctx.shadowColor = ball.color;
      }

      ctx.beginPath();
      ctx.fillStyle = ball.color;
      ctx.arc(p.x, p.y, BALL_RADIUS, 0, Math.PI * 2);
      ctx.fill();

      ctx.shadowBlur = 0;
      ctx.fillStyle = '#fff';
      ctx.font = 'bold 15px Inter, sans-serif';
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.fillText(ball.value.toString(), p.x, p.y);
    });

    projectilesRef.current.forEach((proj) => {
      ctx.beginPath();
      ctx.fillStyle = proj.color;
      ctx.shadowBlur = 15;
      ctx.shadowColor = '#fff';
      ctx.arc(proj.x, proj.y, 11, 0, Math.PI * 2);
      ctx.fill();
      ctx.shadowBlur = 0;

      ctx.fillStyle = '#000';
      ctx.font = 'bold 12px Inter, sans-serif';
      ctx.fillText(proj.value.toString(), proj.x, proj.y);
    });

    effectsRef.current.forEach(eff => {
      ctx.globalAlpha = eff.life;
      if (eff.type === 'particle') {
        ctx.beginPath();
        ctx.fillStyle = eff.color;
        ctx.arc(eff.x, eff.y, eff.size || 3, 0, Math.PI * 2);
        ctx.fill();
      } else {
        ctx.fillStyle = eff.color;
        ctx.shadowBlur = 5;
        ctx.shadowColor = 'rgba(0,0,0,0.5)';
        ctx.font = `bold ${eff.size}px Inter, sans-serif`;
        ctx.fillText(eff.text || '', eff.x, eff.y);
        ctx.shadowBlur = 0;
      }
    });
    ctx.globalAlpha = 1;

    const centerX = canvas.width / 2;
    const centerY = canvas.height / 2;
    ctx.save();
    ctx.translate(centerX, centerY);
    ctx.rotate(shooterAngleRef.current);
    ctx.fillStyle = '#334155';
    ctx.beginPath();
    ctx.roundRect(-22, -18, 65, 36, 10);
    ctx.fill();
    ctx.fillStyle = '#0ea5e9';
    ctx.fillRect(38, -6, 6, 12);
    ctx.restore();

    ctx.beginPath();
    ctx.fillStyle = '#0f172a';
    ctx.strokeStyle = '#0ea5e9';
    ctx.lineWidth = 4;
    ctx.arc(centerX, centerY, 38, 0, Math.PI * 2);
    ctx.fill();
    ctx.stroke();

    ctx.fillStyle = '#fff';
    ctx.font = 'bold 26px Inter, sans-serif';
    ctx.fillText(currentBallValueRef.current.toString(), centerX, centerY);

    ctx.font = 'bold 13px Inter, sans-serif';
    ctx.fillStyle = 'rgba(255,255,255,0.7)';
    ctx.fillText('SIGUIENTE: ' + nextBallValueRef.current.toString(), centerX, centerY + 58);

    ctx.restore();
  }, [gameState, targetNumber, gameMode]);

  useEffect(() => {
    pathRef.current = generatePath(800, 600);
    if (gameState === 'playing') {
      requestRef.current = requestAnimationFrame(update);
    }
    return () => {
      if (requestRef.current) cancelAnimationFrame(requestRef.current);
    };
  }, [gameState]);

  const startGame = (mode: GameMode) => {
    setGameMode(mode);
    setGameState('playing');
    initLevel(1, mode);
  };

  const restartGame = () => {
    setGameState('playing');
    initLevel(1, gameMode);
  };

  const nextLevel = () => {
    setGameState('playing');
    initLevel(level + 1, gameMode);
  };

  useEffect(() => {
    const stored = localStorage.getItem('zuma_math_highscore');
    if (stored) setHighScore(parseInt(stored));
  }, []);

  useEffect(() => {
    if (score > highScore) {
      setHighScore(score);
      localStorage.setItem('zuma_math_highscore', score.toString());
    }
  }, [score, highScore]);

  const tutorialSteps = [
    {
      title: "Bienvenido a Math Zuma",
      desc: "Este es un juego de agilidad mental y puntería. Tu objetivo es limpiar la línea de números antes de que lleguen al centro.",
      icon: <Zap className="w-12 h-12 text-indigo-400" />
    },
    {
      title: "Controles",
      desc: "Mueve el ratón para apuntar tu torreta central. Haz clic para disparar la esfera numérica actual.",
      icon: <Play className="w-12 h-12 text-indigo-400" />
    },
    {
      title: "La Regla de Oro",
      desc: "Solo puedes eliminar esferas si el número que disparas Y el número al que golpeas cumplen la condición del nivel (Múltiplos o Divisores).",
      icon: <Target className="w-12 h-12 text-emerald-400" />
    },
    {
      title: "Múltiplos y Divisores",
      desc: "En modo Múltiplos, busca números que resulten de multiplicar el objetivo. En modo Divisores, busca números que puedan dividir al objetivo exactamente.",
      icon: <Target className="w-12 h-12 text-cyan-400" />
    },
    {
      title: "Peligro: El Vacío",
      desc: "Si una sola esfera llega al agujero negro central, la partida terminará. ¡Mantén la línea bajo control!",
      icon: <AlertTriangle className="w-12 h-12 text-rose-500" />
    }
  ];

  return (
    <div className="min-h-screen bg-slate-950 text-white font-sans flex flex-col items-center justify-center overflow-hidden selection:bg-indigo-500/30">
      {/* HUD */}
      {gameState === 'playing' && (
        <div className="absolute top-0 left-0 w-full p-6 flex justify-between items-start pointer-events-none z-10">
          <div className="bg-slate-900/90 backdrop-blur-xl p-5 rounded-3xl border border-white/10 shadow-2xl ring-1 ring-white/5">
            <div className="flex items-center gap-3 mb-1">
              <div className="p-2 bg-indigo-500/20 rounded-xl">
                <Target className="w-5 h-5 text-indigo-400" />
              </div>
              <span className="text-slate-400 text-xs font-bold uppercase tracking-[0.2em]">Misión de Nivel</span>
            </div>
            <h2 className="text-2xl font-black tracking-tight">
              {gameMode === 'multiples' ? 'Múltiplos' : 'Divisores'} de{' '}
              <span className="text-indigo-400 px-2 py-0.5 bg-indigo-400/10 rounded-lg">{targetNumber}</span>
            </h2>
          </div>

          <div className="flex flex-col items-end gap-3">
            <div className="bg-slate-900/90 backdrop-blur-xl p-5 rounded-3xl border border-white/10 shadow-2xl ring-1 ring-white/5 min-w-[160px]">
              <div className="text-slate-400 text-[10px] font-bold uppercase tracking-[0.2em] mb-1 text-right">Puntuación</div>
              <div className="text-4xl font-black text-right tabular-nums text-transparent bg-clip-text bg-gradient-to-br from-white to-slate-500">
                {score.toLocaleString()}
              </div>
            </div>
            <div className="bg-indigo-600 px-5 py-2 rounded-2xl border border-white/10 shadow-xl text-sm font-black tracking-widest uppercase">
              NIVEL {level}
            </div>
          </div>
        </div>
      )}

      {/* Main Canvas Area */}
      <div className="relative">
        <canvas
          ref={canvasRef}
          width={800}
          height={600}
          onMouseMove={handleMouseMove}
          onClick={handleShoot}
          className={`rounded-[2.5rem] shadow-[0_0_100px_rgba(0,0,0,0.5)] bg-slate-900/50 border border-white/5 transition-all duration-700 ${gameState !== 'playing' ? 'opacity-30 blur-sm scale-95 pointer-events-none' : 'opacity-100 scale-100'}`}
        />

        {/* Menu Overlays */}
        {gameState === 'menu' && (
          <div className="absolute inset-0 flex flex-col items-center justify-center bg-slate-950/40 backdrop-blur-sm rounded-[2.5rem] p-8 text-center animate-in fade-in zoom-in duration-500">
            <div className="mb-8 p-8 bg-indigo-600 rounded-[2rem] shadow-[0_0_60px_rgba(79,70,229,0.4)] animate-bounce-slow">
              <Zap className="w-20 h-20 text-white fill-current" />
            </div>
            <h1 className="text-7xl font-black mb-4 tracking-tighter bg-clip-text text-transparent bg-gradient-to-b from-white via-white to-slate-500">
              MATH ZUMA
            </h1>
            <p className="text-slate-400 mb-12 max-w-lg text-xl font-medium leading-relaxed">
              El reto definitivo de agilidad mental. Elimina las esferas numéricas antes de que el vacío las consuma.
            </p>

            <div className="grid grid-cols-2 gap-8 w-full max-w-xl mb-8">
              <button
                onClick={() => startGame('multiples')}
                className="group relative flex flex-col items-center p-10 bg-slate-900/80 backdrop-blur-md border border-white/5 rounded-[2rem] hover:border-indigo-500 transition-all hover:-translate-y-2 hover:shadow-[0_30px_60px_-15px_rgba(79,70,229,0.4)]"
              >
                <div className="mb-5 p-5 bg-indigo-500/10 rounded-2xl group-hover:bg-indigo-500/20 transition-colors">
                  <Play className="w-10 h-10 text-indigo-400 fill-current" />
                </div>
                <span className="font-black text-2xl mb-2 tracking-tight">Múltiplos</span>
                <span className="text-slate-500 text-xs font-bold uppercase tracking-widest">N × 1, 2, 3...</span>
              </button>

              <button
                onClick={() => startGame('divisors')}
                className="group relative flex flex-col items-center p-10 bg-slate-900/80 backdrop-blur-md border border-white/5 rounded-[2rem] hover:border-cyan-500 transition-all hover:-translate-y-2 hover:shadow-[0_30px_60px_-15px_rgba(6,182,212,0.4)]"
              >
                <div className="mb-5 p-5 bg-cyan-500/10 rounded-2xl group-hover:bg-cyan-500/20 transition-colors">
                  <Target className="w-10 h-10 text-cyan-400" />
                </div>
                <span className="font-black text-2xl mb-2 tracking-tight">Divisores</span>
                <span className="text-slate-500 text-xs font-bold uppercase tracking-widest">N / X = Entero</span>
              </button>
            </div>

            <div className="flex gap-4">
               <button
                  onClick={() => { setGameState('tutorial'); setTutorialStep(0); }}
                  className="flex items-center gap-3 px-8 py-4 bg-slate-800/80 hover:bg-slate-700 rounded-2xl font-black text-white transition-all border border-white/10 hover:border-indigo-500/50"
                >
                  <BookOpen className="w-6 h-6" />
                  ¿CÓMO JUGAR?
                </button>
            </div>

            <div className="mt-10 flex items-center gap-3 text-slate-500 px-6 py-3 bg-white/5 rounded-full border border-white/5">
              <Trophy className="w-5 h-5 text-amber-500" />
