      .sort((a, b) => b.score - a.score)
      .slice(0, 30);

    setLeaderboard(updatedLeaderboard);
    localStorage.setItem('zuma_math_leaderboard', JSON.stringify(updatedLeaderboard));
    setScoreSaved(true);
